//! Central home for narrow object wrapper types (e.g. `Array`, `Promise`).
//!
//! The `pub struct X(GcRef<ObjectImpl>)` + `object_cast!` boilerplate that used
//! to live scattered across the builtin modules is bulk-generated by
//! `build_stdclass.rs::gen_object_casts` into `$OUT_DIR/object_casts.rs` and
//! `include!`d here. This module must sit inside `crate::object` so that
//! `Object`, `ObjectImpl`, `JSValue`, `GcRef` and the `object_cast!` macro are
//! all in scope for the generated code.

use gc_lite::GcRef;

use crate::{object_cast, value::JSValue};

use super::{Object, ObjectImpl};

include!(concat!(env!("OUT_DIR"), "/object_casts.rs"));
